using System.ComponentModel; using System.Text.RegularExpressions;
namespace GymMemberManager;
public class MainForm:Form {
TextBox txtMemberId=new(){ReadOnly=true},txtFullName=new(),txtPhone=new(),txtFee=new(); ComboBox cboPackage=new(){DropDownStyle=ComboBoxStyle.DropDownList}; DateTimePicker dtpStartDate=new(){Format=DateTimePickerFormat.Short}; DataGridView dgvMembers=new(); BindingList<MemberModel> members=new(); BindingSource bs=new(); ErrorProvider ep=new(); MemberModel? selected; bool loading;
public MainForm(){Text="Gym Member Manager";Width=1100;Height=700;MinimumSize=new Size(850,550);BuildUI();bs.DataSource=members;dgvMembers.DataSource=bs;members.Add(new(){MemberId="HV001",FullName="Nguyễn Minh Anh",Phone="0912345678",Package="Theo tháng",StartDate=DateTime.Today.AddDays(-5),Fee=500000});members.Add(new(){MemberId="HV002",FullName="Trần Quốc Bảo",Phone="0987654321",Package="6 tháng",StartDate=DateTime.Today.AddDays(-3),Fee=2700000});NextId();}
void BuildUI(){ep.ContainerControl=this;var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(10),RowCount=3,ColumnCount=1};root.RowStyles.Add(new(SizeType.Absolute,220));root.RowStyles.Add(new(SizeType.Absolute,45));root.RowStyles.Add(new(SizeType.Percent,100));Controls.Add(root);var g=new GroupBox{Text="Thông tin hội viên",Dock=DockStyle.Fill};var t=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=4,RowCount=2};for(int i=0;i<4;i++)t.ColumnStyles.Add(new(SizeType.Percent,25));for(int i=0;i<2;i++)t.RowStyles.Add(new(SizeType.Percent,50));Add(t,"Mã hội viên",txtMemberId,0,0);Add(t,"Họ và tên",txtFullName,1,0);Add(t,"Số điện thoại",txtPhone,2,0);Add(t,"Gói tập",cboPackage,3,0);Add(t,"Ngày đăng ký",dtpStartDate,0,1);Add(t,"Phí dịch vụ",txtFee,1,1);cboPackage.Items.AddRange(new object[]{"Theo tháng","6 tháng","1 năm"});cboPackage.SelectedIndex=0;g.Controls.Add(t);root.Controls.Add(g,0,0);var p=new FlowLayoutPanel{Dock=DockStyle.Fill};p.Controls.Add(Btn("Thêm mới",(_,_)=>AddMember()));p.Controls.Add(Btn("Sửa thông tin",(_,_)=>EditMember()));p.Controls.Add(Btn("Xóa hội viên",(_,_)=>DeleteMember()));p.Controls.Add(Btn("Làm mới",(_,_)=>Clear()));root.Controls.Add(p,0,1);dgvMembers.Dock=DockStyle.Fill;dgvMembers.AutoGenerateColumns=false;dgvMembers.SelectionMode=DataGridViewSelectionMode.FullRowSelect;dgvMembers.ReadOnly=true;dgvMembers.MultiSelect=false;dgvMembers.AllowUserToAddRows=false;dgvMembers.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;dgvMembers.SelectionChanged+=(_,_)=>LoadRow();Col("Mã HV",nameof(MemberModel.MemberId));Col("Tên hội viên",nameof(MemberModel.FullName));Col("SĐT",nameof(MemberModel.Phone));Col("Gói tập",nameof(MemberModel.Package));Col("Ngày ĐK",nameof(MemberModel.StartDate),"dd/MM/yyyy");Col("Phí dịch vụ",nameof(MemberModel.Fee),"N0");root.Controls.Add(dgvMembers,0,2);}
void Add(TableLayoutPanel t,string label,Control c,int x,int y){var p=new Panel{Dock=DockStyle.Fill,Padding=new Padding(5)};var s=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=2};s.RowStyles.Add(new(SizeType.Absolute,25));s.RowStyles.Add(new(SizeType.Percent,100));s.Controls.Add(new Label{Text=label,Dock=DockStyle.Fill},0,0);c.Dock=DockStyle.Fill;s.Controls.Add(c,0,1);p.Controls.Add(s);t.Controls.Add(p,x,y);}
Button Btn(string text,EventHandler e){var b=new Button{Text=text,Width=135,Height=32,Margin=new Padding(5)};b.Click+=e;return b;} void Col(string h,string p,string? f=null){var c=new DataGridViewTextBoxColumn{HeaderText=h,DataPropertyName=p};if(f!=null)c.DefaultCellStyle.Format=f;dgvMembers.Columns.Add(c);}
void NextId(){int n=members.Select(m=>int.TryParse(m.MemberId.Replace("HV",""),out int x)?x:0).DefaultIfEmpty().Max()+1;txtMemberId.Text=$"HV{n:000}";}
bool Valid(){ep.Clear();bool ok=true;if(string.IsNullOrWhiteSpace(txtFullName.Text)||!Regex.IsMatch(txtFullName.Text.Trim(),@"^[\p{L}\p{M} ]+$")){ep.SetError(txtFullName,"Tên không được trống hoặc chứa ký tự đặc biệt.");ok=false;}if(!Regex.IsMatch(txtPhone.Text.Trim(),@"^\d{10}$")){ep.SetError(txtPhone,"Số điện thoại phải đúng 10 chữ số.");ok=false;}if(!decimal.TryParse(txtFee.Text,out decimal fee)||fee<=0||fee!=decimal.Truncate(fee)){ep.SetError(txtFee,"Phí phải là số nguyên dương.");ok=false;}return ok;}
void AddMember(){if(!Valid())return;members.Add(new(){MemberId=txtMemberId.Text,FullName=txtFullName.Text.Trim(),Phone=txtPhone.Text.Trim(),Package=cboPackage.Text,StartDate=dtpStartDate.Value.Date,Fee=decimal.Parse(txtFee.Text)});bs.ResetBindings(false);Clear();}
void EditMember(){if(selected==null){MessageBox.Show("Chọn hội viên cần sửa.");return;}if(!Valid())return;selected.FullName=txtFullName.Text.Trim();selected.Phone=txtPhone.Text.Trim();selected.Package=cboPackage.Text;selected.StartDate=dtpStartDate.Value.Date;selected.Fee=decimal.Parse(txtFee.Text);bs.ResetBindings(false);dgvMembers.Refresh();}
void DeleteMember(){if(selected==null){MessageBox.Show("Chọn hội viên cần xóa.");return;}if(MessageBox.Show("Bạn có chắc chắn muốn xóa hội viên?","Xác nhận",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;members.Remove(selected);selected=null;bs.ResetBindings(false);Clear();}
void LoadRow(){if(loading||dgvMembers.CurrentRow?.DataBoundItem is not MemberModel m)return;loading=true;selected=m;txtMemberId.Text=m.MemberId;txtFullName.Text=m.FullName;txtPhone.Text=m.Phone;cboPackage.Text=m.Package;dtpStartDate.Value=m.StartDate;txtFee.Text=m.Fee.ToString("0");loading=false;}
void Clear(){loading=true;selected=null;txtFullName.Clear();txtPhone.Clear();txtFee.Clear();cboPackage.SelectedIndex=0;dtpStartDate.Value=DateTime.Today;ep.Clear();dgvMembers.ClearSelection();NextId();loading=false;}
}